package gg.hera.features;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;
class WorldVisualPolicyTest {
 @Test void changedTimePreservesTheDayAndMoonCycle(){for(long original:new long[]{0,23999,24000,987654321,-1,-24001}){long changed=WorldVisualPolicy.time(original,6000);assertEquals(Math.floorDiv(original,24000),Math.floorDiv(changed,24000));assertEquals(6000,Math.floorMod(changed,24000));}assertEquals(Long.MIN_VALUE,WorldVisualPolicy.time(Long.MIN_VALUE,0));assertEquals(Long.MAX_VALUE,WorldVisualPolicy.time(Long.MAX_VALUE,23999));}
 @Test void fullBrightNeverDarkensAnAlreadyBrightDimension(){assertEquals(.8f,WorldVisualPolicy.brightness(.8f,.2f));assertEquals(1,WorldVisualPolicy.brightness(.1f,1));assertEquals(.5f,WorldVisualPolicy.brightness(0,.5f));}
 @Test void allWeatherModesRespectIntensityAndRainCoupling(){assertEquals(0,WorldVisualPolicy.rain(0,1));assertEquals(.6f,WorldVisualPolicy.rain(1,.6f));assertEquals(0,WorldVisualPolicy.thunder(1,1,1));assertEquals(.3f,WorldVisualPolicy.thunder(2,.6f,.5f));assertEquals(0,WorldVisualPolicy.thunder(2,0,1));}
 @Test void fogFlagsAndLavaOverrideRemainIndependent(){var o=new ModuleOptions();for(var medium:WorldVisualPolicy.Medium.values())assertFalse(WorldVisualPolicy.removeFog(o,false,medium));o.noFog=true;assertTrue(WorldVisualPolicy.removeFog(o,false,WorldVisualPolicy.Medium.AIR));o.fogAir=false;assertFalse(WorldVisualPolicy.removeFog(o,false,WorldVisualPolicy.Medium.AIR));o.fogPowderSnow=false;assertFalse(WorldVisualPolicy.removeFog(o,false,WorldVisualPolicy.Medium.POWDER_SNOW));o.fogWater=false;assertFalse(WorldVisualPolicy.removeFog(o,false,WorldVisualPolicy.Medium.WATER));o.fogLava=false;assertFalse(WorldVisualPolicy.removeFog(o,false,WorldVisualPolicy.Medium.LAVA));o.noFog=false;assertTrue(WorldVisualPolicy.removeFog(o,true,WorldVisualPolicy.Medium.LAVA));assertFalse(WorldVisualPolicy.removeFog(o,true,WorldVisualPolicy.Medium.WATER));}
 @Test void oldOptionsKeepPreviousVisualStrengthAndNewValuesAreValidated(){var o=new com.google.gson.Gson().fromJson("{}",ModuleOptions.class);assertEquals(1,o.weatherRain);assertEquals(1,o.weatherThunder);assertTrue(o.zoomSmooth);assertTrue(o.fogAir&&o.fogPowderSnow);o.weatherRain=Float.NaN;o.weatherThunder=-20;o.normalize();assertEquals(1,o.weatherRain);assertEquals(0,o.weatherThunder);assertEquals("06:00",WorldVisualPolicy.timeLabel(0));assertEquals("00:00",WorldVisualPolicy.timeLabel(18000));}
}
